export function mountAdminHealth(root,client,isCurrent){
 const panel=document.createElement('details');panel.className='panel admin-health';panel.innerHTML='<summary>ตรวจสถานะระบบ</summary><p class="sub">ตรวจการเชื่อมต่อระบบสมัครและฐานข้อมูล ปัญหาภายในระบบบันทึกเฉพาะประเภทข้อผิดพลาด ไม่มีชื่อ อีเมล เบอร์โทร หรือรหัสบัตร</p><button type="button">ตรวจการเชื่อมต่อ</button><p role="status"></p>';root.append(panel);
 const button=panel.querySelector('button'),status=panel.querySelector('[role=status]');button.onclick=async()=>{button.disabled=true;status.textContent='กำลังตรวจ…';try{const result=await client.operate({action:'health'});if(!isCurrent()||!panel.isConnected)return;status.textContent=result.ok?'เชื่อมต่อระบบและฐานข้อมูลได้ · '+new Date(result.checkedAt).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}):'ระบบยังไม่พร้อม'}catch(error){if(isCurrent()&&panel.isConnected)status.textContent='ตรวจไม่สำเร็จ กรุณาตรวจอินเทอร์เน็ตแล้วลองใหม่'}finally{button.disabled=false}};
 const links=document.createElement('p');links.className='sub';const consoleLink=document.createElement('a');consoleLink.href='https://console.cloud.google.com/monitoring/alerting?project=kusk-register';consoleLink.target='_blank';consoleLink.rel='noopener noreferrer';consoleLink.textContent='ดูเหตุขัดข้องใน Google Cloud →';links.append(consoleLink);panel.append(links);
}
